import { test } from 'node:test';
import assert from 'node:assert/strict';
import { selectSimulado } from './solution.mjs';

const linhas = [
  { id: 1, nome: 'estudar', feito: 0 },
  { id: 2, nome: 'exercitar', feito: 1 },
  { id: 3, nome: 'cozinhar', feito: 0 },
];

test('devolve as linhas que batem com o filtro', () => {
  assert.deepEqual(selectSimulado(linhas, 'feito', 0), [
    { id: 1, nome: 'estudar', feito: 0 },
    { id: 3, nome: 'cozinhar', feito: 0 },
  ]);
});

test('devolve a linha exata ao filtrar pelo id', () => {
  assert.deepEqual(selectSimulado(linhas, 'id', 2), [
    { id: 2, nome: 'exercitar', feito: 1 },
  ]);
});

test('devolve lista vazia quando nada bate, e também para lista vazia', () => {
  assert.deepEqual(selectSimulado(linhas, 'feito', 9), []);
  assert.deepEqual(selectSimulado([], 'feito', 0), []);
});

test('lança erro quando a coluna não existe', () => {
  assert.throws(() => selectSimulado(linhas, 'concluida', 1), /concluida/);
});

solutionCode:
// SELECT simulado: devolve as linhas onde linha[coluna] === valor,
// como um SELECT ... WHERE coluna = valor faria num banco de verdade.
export function selectSimulado(linhas, coluna, valor) {
  // a primeira linha mostra se a coluna existe; lista vazia não tem coluna
  const primeira = linhas[0];
  if (primeira && primeira[coluna] === undefined) {
    throw new Error(`coluna '${coluna}' não existe`);
  }
  return linhas.filter((linha) => linha[coluna] === valor);
}
